with d as (select value r from jsonb_array_elements($q$[{"notes":["Store in an airtight container for up to 5 days.","You can make this in a conventional oven at 180°C if you don't have a camp oven, bake for 18–20 minutes.","If you can't find wattleseed flour locally, use the same weight of plain flour instead, though you'll lose the earthy, distinctive flavour."],"id":"04107595-1117-44d7-b5fa-149f1076057a"},{"notes":["Make the filling ahead: it keeps in the fridge for up to 3 days. Warm it gently before stuffing.","If you don't have a tawa, use a flat non-stick frying pan or cast iron frying pan.","The dough can be made and left covered for up to 1 hour before rolling."],"id":"3b87b180-96ee-4346-851d-5eea65b11e4c"},{"notes":["Use jarred vine leaves if fresh aren't available. Rinse off the brine and pat dry.","Any whole white fish works: bream, snapper, flathead. Aim for 350–450 g per fish.","The blackened leaves are not meant to be eaten. Unwrap carefully and discard.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Light your charcoal and let it burn down to glowing coals. You want heat, not flame."},{"text":"Pat the fish dry inside and out. Season the cavity with salt, pepper and a pinch of oregano. Stuff each fish with 2 lemon slices and 1 oregano sprig."},{"text":"Lay 6 vine leaves on a work surface, overlapping them to form a base. Place a fish on top, then fold the leaves up and around it, tucking and overlapping to seal it completely. Do the same with the other fish."},{"text":"Brush each parcel lightly with olive oil. Place on the grill grate over the coals and cook until the leaves are charred and the fish flakes easily and is opaque inside."},{"text":"Cook for 10–12 minutes until the vine leaves are charred black on top. Flip the parcel carefully, then cook for another 8–10 minutes on the other side until the second side is charred and the fish is cooked through (the flesh should be opaque and flake easily at the thickest part)."},{"text":"Slide onto a plate and let rest for 2 minutes. Unwrap at the table. The leaves are burnt, but the fish inside is perfect, steamed in its own juices with lemon and herb."}],"id":"170ad0a7-4633-49bf-a3b7-365309974518"},{"notes":["The dough can be made up to 4 hours ahead and kept covered at room temperature. If you're short on time, you can stretch the noodles thinner and cook them a little faster, just watch they don't break.","You can use beef mince instead of lamb; the cumin-to-meat ratio stays the same. Some cooks add a handful of fresh coriander or a drizzle of chilli oil to finish.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"893ddd7b-43a0-4148-8452-80c07187f1d4"},{"notes":["Kokotxas are expensive and seasonal. Buy them very fresh from a good fishmonger, or ask them to order them in.","The sauce must never boil after the egg yolks are added, or it will scramble. Keep the heat low.","Don't skip the white pepper, it's gentler than black and won't speckle the delicate pale sauce.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Put the kokotxas in a wide, shallow pan with the white wine and fish stock. Bring to a gentle simmer and poach for 3 to 4 minutes, until just cooked through, they should be opaque but still delicate. Carefully transfer the kokotxas to a warm plate with a slotted spoon, keeping the cooking liquid in the pan."},{"text":"Heat the olive oil in another pan over low heat. Add the sliced garlic and cook gently, stirring, until it is just starting to soften and colour, about 2 minutes. Do not burn it."},{"text":"Pour the cooking liquid (about 300 ml) into the pan with the garlic and oil, and bring to a simmer. Add the chopped parsley and cook for 1 minute."},{"text":"In a small bowl, beat the egg yolks lightly. Remove the pan from the heat, let it cool for 30 seconds, then slowly pour in the egg yolks while whisking constantly, this makes the sauce silky and rich without scrambling the eggs. Taste and season with salt and white pepper."},{"text":"Gently return the kokotxas to the pan and warm through for 30 seconds without letting the sauce boil, until the fish is just opaque and the sauce is glossy."},{"text":"Divide among four bowls, pour the salsa verde over and around the kokotxas, and serve with crusty bread to soak up every drop."}],"id":"3cef10c2-eebc-45f4-98c7-481eef5610c0"},{"notes":["If you can't find fideuà noodles, break thin spaghetti or vermicelli into short pieces before toasting.","The socarrat is crucial, that dark, crackling crust at the bottom. Listen for it; don't walk away during those last 30 seconds.","Make the aioli ahead if you like; it keeps in the fridge for a day.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Make the aioli first: in a mortar or small bowl, pound the garlic with a pinch of salt until smooth. Add the egg yolk and stir well. Add the oil a drop at a time, whisking constantly, until it begins to emulsify. Once thickened, add the oil in a thin stream, whisking continuously. Finish with lemon juice and salt. Set aside."},{"text":"Heat the oil in a paella pan or large shallow frying pan (about 30 cm) over medium heat. Add the noodles and toast, stirring often, until they turn golden and fragrant, about 3 to 4 minutes. Remove and set aside."},{"text":"In the same pan, heat a little more oil if needed and soften the onion, garlic and capsicum over medium heat, stirring often, until soft and translucent, about 8 minutes. This sofregit should be slow and gentle, don't rush it."},{"text":"Add the tomato and cook for 2 minutes, stirring."},{"text":"Return the toasted noodles to the pan and stir to coat. Pour in the warm stock and the saffron with its soaking water. Bring to a simmer and cook without stirring for about 10 minutes, until most of the liquid has been absorbed and the noodles are tender."},{"text":"Scatter the prawns and squid over the top, season with salt and pepper, and continue cooking for about 5 minutes, stirring gently, until the prawns are cooked through (opaque and firm) and the squid is tender."},{"text":"Increase the heat to medium-high for the last minute to create the socarrat, listen for a gentle crackling sound from the bottom. Don't burn it; you want a dark, crispy crust, not black."},{"text":"Remove from heat. Scatter with fresh parsley and serve straight from the pan with the aioli on the side."}],"id":"b1c18605-427a-4da8-b908-7dea5542b995"},{"notes":["Make it no more than an hour or two before serving, the cucumbers release water over time and the salad becomes watery.","If using English cucumbers (continental), use 2 large ones and skip peeling if you prefer, the skin is thin and tender."],"id":"77d20dce-f12e-4f0a-8b4c-ba216abde01d"},{"notes":["Holds well in a low oven (150°C) for 30 minutes if dinner runs late.","Use waxy potatoes like Kipfler or baby potatoes, they hold their shape. Don't use floury potatoes.","If your anchovies are very salty, rinse and pat them dry first."],"steps":[{"text":"Heat the oven to 200°C. Butter a 2-litre baking dish."},{"text":"Layer half the potatoes into the dish, then half the onion and half the anchovies. Season lightly with salt and pepper (go easy on the salt, the anchovies are already salty). Repeat with the remaining potatoes, onion, and anchovies."},{"text":"Whisk the cream and milk together, then pour over the potato layers. Stir gently to distribute the anchovies and onions, but don't mash the potatoes. Scatter the remaining butter in small pieces on top. If you want a crust, sprinkle the panko over the butter."},{"text":"Bake for 45–50 minutes, until the potatoes are tender and the top is golden. If the top browns too fast, cover loosely with foil and uncover for the last 10 minutes to crisp up."},{"text":"Let it rest for 5 minutes, then serve warm straight from the dish."}],"id":"4f5ff4f8-0cf1-4828-b8d1-690220a83d66"},{"steps":[{"text":"Heat the oil in a large frying pan over medium-high heat. Season the trout inside and out with salt and pepper. When the oil shimmers, lay the trout in the pan and cook for 6–7 minutes without moving them, until the skin is golden and crisp."},{"text":"Carefully turn the trout and cook for another 4–5 minutes on the other side, until the flesh is just cooked through and flakes gently at the thickest part near the backbone. Transfer to a warm plate."},{"text":"Reduce the heat to medium. Add the butter to the same pan and let it melt, swirling often. After 2–3 minutes, the butter will begin to foam. Keep swirling until the milk solids turn golden and the butter smells nutty, about 1–2 minutes more."},{"text":"Add the hazelnuts to the brown butter and stir gently for 30 seconds, until the hazelnuts are golden and fragrant. Pour the hazelnut brown butter over the trout. Serve with lemon wedges and parsley scattered over, if using."}],"id":"dea859d4-025d-426d-8b60-3923e5e4253d"},{"notes":["The fish cake is essential, it's what makes this feel authentic. Find it at Asian grocers or substitute firm tofu if needed.","Make the gravy up to 4 hours ahead and reheat gently before serving; the flavours deepen. Boil the eggs separately to avoid overcooking.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Bring a small pot of water to the boil and gently lower in the eggs. Boil for 7 minutes for firm but slightly runny yolks, or 10 minutes for hard-boiled. Cool in cold water, then peel and halve."},{"text":"Heat the oil in a large pot over medium heat. Fry the shallots until golden and crispy, about 5 minutes, then add the garlic and cook for 30 seconds until fragrant."},{"text":"Add the laksa paste and fry, stirring, for 1 minute. Add the tamarind paste and stir through, then pour in the coconut milk and stock, stirring to combine."},{"text":"Add the palm sugar and turmeric, then bring to a gentle simmer. Cook for 8 to 10 minutes, stirring occasionally, until the gravy thickens slightly. Taste and season with salt and pepper."},{"text":"While the gravy simmers, bring a separate pot of salted water to the boil and cook the egg noodles according to packet directions. Drain and set aside."},{"text":"In the last minute of simmering the gravy, add the fish cake slices and bean sprouts, stirring gently."},{"text":"Divide the noodles between two bowls. Pour the gravy over each bowl, then top with the egg halves, spring onions, fried shallots and fresh chilli if you like. Serve with a lime wedge on the side."},{"text":"Squeeze the lime over just before eating, it lifts the whole thing."}],"id":"8ac6486a-9b67-48b7-85d0-3946840c77dc"},{"steps":[{"text":"Preheat the oven to 160°C. Line a 20 cm square baking tin with baking paper."},{"text":"Rub the cold butter into the flour and salt with your fingertips until the mixture resembles fine breadcrumbs. Don't overwork it."},{"text":"Stir in the caster sugar until just combined. The dough will be crumbly and hold together only loosely."},{"text":"Press the dough evenly into the prepared tin, using the back of a spoon or your fingers. It should be about 1 cm thick."},{"text":"Bake for 20–25 minutes, until pale golden and just firm to the touch. It will still feel slightly soft in the middle, that's correct."},{"text":"Remove from the oven and let cool in the tin for 5 minutes, then cut into fingers or squares while still warm. Leave to cool completely on the tin before lifting out."}],"id":"e5a606eb-4e05-4ab0-92b0-b1fa216d079c"},{"notes":["Serve with rice and peas, or white rice and a green salad.","The Scotch bonnet stays whole so you can fish it out, leave it in if you like heat, or use a milder green chilli instead.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Pat the chicken dry. Heat the oil in a large heavy-bottomed pot over medium-high heat. Working in batches, brown the chicken pieces, turning them until deeply caramelised all over, about 8–10 minutes per batch. Remove to a plate."},{"text":"Reduce the heat to medium. Add the onion and garlic to the pot, and cook, stirring, until soft and fragrant, about 3 minutes."},{"text":"Stir in the tomato paste, allspice, black pepper and salt. Cook for 1 minute, then pour in the stock and add the sugar."},{"text":"Return the chicken to the pot. Add the whole Scotch bonnet and thyme. Bring to a simmer, then reduce the heat to low, cover with a lid, and cook for 30 minutes, turning the chicken halfway through. The chicken should be cooked through (the thickest part reaching 75°C inside)."},{"text":"Taste the broth and add more salt if needed. Remove the whole Scotch bonnet before serving, it will have infused the stew with flavour without overwhelming it."}],"id":"06f71dda-0790-42e6-9dc8-cbee78967335"},{"notes":["Rice cakes keep in the freezer. No need to thaw, just separate and add straight to the boiling stock.","Swap the carrots for whatever's in the crisper: daikon, mushrooms, bok choy, even spinach all work."],"id":"99ef9cb3-7dec-49f7-b334-34fc284ae74a"},{"notes":["Make the dough the night before and refrigerate, it gives better flavour and texture.","The chole can be made up to 2 days ahead; reheat gently before serving.","Don't skip frying the bhatures to order; they're best eaten warm and puffy straight from the oil."],"id":"0f409082-c2df-433f-8c15-9424779bc121"},{"notes":["Mafé tastes better the next day as the flavours deepen. Make it ahead and reheat gently.","You can swap the pumpkin for sweet potato or potato, and the eggplant for green beans or okra.","Serve with plain white rice, or with fried plantain on the side for the kids.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"8e6b426a-8e8b-40a9-a103-f2c36bd7182b"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;